// state = what the tool last built (the recorded state file)
var state = {
  'aws_lb.web':  { instances: 2, sg: 'sg-allow-443' },
  'aws_db.main': { size: 'db.t3.medium', multi_az: false },
  'aws_s3.logs': { versioning: true }
};
// config = desired state in your .tf files
var config = {
  'aws_lb.web':    { instances: 3, sg: 'sg-allow-443' },
  'aws_db.main':   { size: 'db.t3.medium', multi_az: false },
  'aws_cache.sess': { engine: 'redis', nodes: 1 }
};
function keys(o){var k=[];for(var n in o)k.push(n);k.sort();return k;}
function changed(a,b){var ch=[],seen={},ka=keys(a);for(var i=0;i<ka.length;i++){var k=ka[i];seen[k]=1;if(b[k]!==a[k])ch.push(k);}var kb=keys(b);for(var j=0;j<kb.length;j++){if(!seen[kb[j]])ch.push(kb[j]);}ch.sort();return ch;}
var create=[],update=[],destroy=[];
var ck=keys(config);
for(var i=0;i<ck.length;i++){var r=ck[i];if(!state[r]){create.push(r);}else{var d=changed(state[r],config[r]);if(d.length)update.push(r+' ['+d.join(',')+']');}}
var sk=keys(state);
for(var j=0;j<sk.length;j++){var s=sk[j];if(!config[s])destroy.push(s);}
console.log('Plan: '+create.length+' to add, '+update.length+' to change, '+destroy.length+' to destroy');
console.log('+ '+(create.join(' ')||'(none)'));
console.log('~ '+(update.join(' ')||'(none)'));
console.log('- '+(destroy.join(' ')||'(none)'));
